// The runtime obligation tree an answer must discharge before it may finish
// (rust/src/obligation_ledger.rs, rust/src/obligation_ledger/derivation.rs).
//
// Shapes (Rust enum -> tagged object):
// - expectation: `{kind: 'file_bytes', path, sha256: string|null}`,
//   `{kind: 'command_exit', command, expected_exit}`, `{kind: 'output_hash',
//   command, sha256}`, `{kind: 'symbolic_check', check_id}`,
//   `{kind: 'underivable', reason}`; `kind` is `ObligationExpectation::slug`.
// - outcome: `{kind: 'unattempted'}`, `{kind: 'refuted', record, mismatch}`,
//   `{kind: 'satisfied', record}`, `{kind: 'unsatisfiable', reason}`.
// - node: `{node_id, parent, clause, span: [start, end], need_id, depth,
//   expectation, outcome, children}`; `span` is UTF-8 bytes, as in Rust.
// The `ProblemFrame` / `NeedLedger` bridge and the Links Notation projections
// are not ported (the agentic planner reads neither).

import { cached, readText } from '../host.mjs';
import { composeGeneralChangePlan } from '../general_planner.mjs';
import { findChildValue, parseLinoRoot } from '../write_lino.mjs';
import { wordsForRole } from '../write_lexicon.mjs';
import { isAlphanumeric, isWhitespace, lines, trim, trimEnd, trimEndMatches, utf8Len } from '../write_str.mjs';
import { debugOption, stableId } from './engine_stable_identifier.mjs';
import { evidenceNames, reportsSuccess } from './execution_evidence.mjs';
import { detect } from './language.mjs';
import { sha256Hex } from './source_fetch.mjs';
import { isCheckable, splitOnceCheckable } from './task_decomposition.mjs';

const encoder = new TextEncoder();

/** Mirrors `ObligationExpectation::is_observable`. */
export function isObservable(expectation) {
  return expectation.kind !== 'underivable';
}

/** Mirrors `fn clauses_with_spans`: `[clause, [start, end]]` in UTF-8 bytes. */
export function clausesWithSpans(request) {
  const cues = wordsForRole('enumeration_cue');
  if (!cues.length) return [[trim(request), [0, utf8Len(request)]]];
  const boundaries = [0];
  for (let index = 0; index < request.length; index += request.codePointAt(index) > 0xffff ? 2 : 1) {
    if (index === 0 || !opensAClause(request, index)) continue;
    const rest = request.slice(index).toLowerCase();
    if (cues.some((cue) => startsWithCue(rest, cue))) boundaries.push(index);
  }
  boundaries.push(request.length);
  const unique = boundaries.filter((value, at) => at === 0 || value !== boundaries[at - 1]);
  const out = [];
  for (let at = 0; at + 1 < unique.length; at += 1) {
    const raw = request.slice(unique[at], unique[at + 1]);
    const trimmed = trim(raw);
    if (trimmed === '') continue;
    const start = utf8Len(request.slice(0, unique[at] + raw.indexOf(trimmed)));
    out.push([trimmed, [start, start + utf8Len(trimmed)]]);
  }
  return out;
}

/**
 * Mirrors `fn opens_a_clause`: the line break is read before trimming, so a
 * cue opening a new line cuts even when the previous line ends without a
 * sentence mark (issue #1166).
 */
function opensAClause(request, index) {
  const lineEnd = trimEndMatches(request.slice(0, index), (character) => [' ', '\t', '\r'].includes(character));
  const before = trimEnd(lineEnd);
  return before === '' || lineEnd.endsWith('\n') || ['.', '!', '?', ';', ':', '。', '！', '？', '।', '॥'].some((mark) => before.endsWith(mark));
}

/** @param {string} character */
function isUnspacedScript(character) {
  const cp = character.codePointAt(0);
  return (cp >= 0x3040 && cp <= 0x30ff) || (cp >= 0x3400 && cp <= 0x4dbf) || (cp >= 0x4e00 && cp <= 0x9fff)
    || (cp >= 0xac00 && cp <= 0xd7af) || (cp >= 0xf900 && cp <= 0xfaff);
}

function startsWithCue(rest, cue) {
  if (!rest.startsWith(cue)) return false;
  if (Array.from(cue).some(isUnspacedScript)) return true;
  const next = Array.from(rest.slice(cue.length))[0];
  return next === undefined || !isAlphanumeric(next);
}

/** Mirrors `ExpectationRules::shipped` (`from_lino`). */
export function expectationRules() {
  return cached('write:obligation_rules', () => {
    const rules = [];
    for (const line of lines(readText('data/meta/obligation-evidence-contract.lino'))) {
      const trimmed = trim(line);
      if (trimmed.startsWith('rule ')) {
        rules.push({ name: unquoted(trim(trimmed.slice(5))), when: '', mode: '', expectation: '', otherwise: null, reason: '' });
        continue;
      }
      const rule = rules[rules.length - 1];
      if (!rule) continue;
      for (const key of ['when', 'mode', 'expectation', 'otherwise', 'reason']) {
        const value = field(trimmed, key);
        if (value !== null) {
          rule[key] = value;
          break;
        }
      }
    }
    return rules;
  });
}

function field(line, key) {
  if (!line.startsWith(key)) return null;
  const rest = line.slice(key.length);
  const first = Array.from(rest)[0];
  if (first === undefined || !isWhitespace(first)) return null;
  return unquoted(trim(rest));
}

function unquoted(raw) {
  return raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"') ? raw.slice(1, -1) : raw;
}

const ruleWhen = (when) => expectationRules().find((rule) => rule.when === when) ?? null;

/** Mirrors `fn expected_digest`. */
export function expectedDigest(content) {
  let stated = trimEnd(content);
  const last = Array.from(stated).pop();
  if (last !== undefined && ['.', '。', '।', '!', '？', '?'].includes(last)) stated = stated.slice(0, -last.length);
  stated = trimEnd(stated);
  if (stated === '') return null;
  const normalized = stated.endsWith('\n') ? stated : `${stated}\n`;
  return sha256Hex(encoder.encode(normalized));
}

/** Mirrors `fn derive_expectation`. */
export function deriveExpectation(clause) {
  const plan = composeGeneralChangePlan(clause);
  if (plan !== null) {
    return shapeFor(plan, expectationRules().find((rule) => rule.when === 'general_plan_mode' && rule.mode === plan.mode) ?? null);
  }
  if (isCheckable(clause)) {
    const rule = ruleWhen('generated_check');
    if (rule === null || rule.expectation === 'symbolic_check') {
      return { kind: 'symbolic_check', check_id: `obligation:${stableId('obligation_check', trim(clause))}` };
    }
  }
  return { kind: 'underivable', reason: ruleWhen('no_artifact')?.reason ?? 'no_artifact_in_clause' };
}

function shapeFor(plan, rule) {
  if (rule === null) return { kind: 'underivable', reason: `no_rule_for_plan_mode_${plan.mode}` };
  const declared = expectedDigest(plan.content);
  const shape = declared === null && rule.otherwise !== null ? rule.otherwise : rule.expectation;
  const commandExit = { kind: 'command_exit', command: plan.verification_command, expected_exit: 0 };
  switch (shape) {
    case 'file_bytes': return { kind: 'file_bytes', path: plan.target, sha256: declared };
    case 'output_hash': return declared === null ? commandExit : { kind: 'output_hash', command: plan.verification_command, sha256: declared };
    case 'command_exit': return commandExit;
    case 'symbolic_check': return { kind: 'symbolic_check', check_id: `obligation:${stableId('obligation_check', plan.goal)}` };
    default: return { kind: 'underivable', reason: rule.reason };
  }
}

/** Mirrors `ObligationNode::leaf`. */
export function leafNode(parent, clause, span, depth, expectation) {
  const trimmed = trim(clause);
  return {
    node_id: stableId('obligation', `${debugOption(parent)}:${depth}:${trimmed}`),
    parent,
    clause: trimmed,
    span,
    need_id: null,
    depth,
    expectation,
    outcome: { kind: 'unattempted' },
    children: [],
  };
}

/** Mirrors `ObligationNode::build`. */
export function buildObligationTree(request, maxSplitDepth) {
  const root = leafNode(null, request, [0, utf8Len(request)], 0, deriveExpectation(request));
  const clauses = clausesWithSpans(request);
  if (clauses.length < 2) {
    expand(root, maxSplitDepth);
    return root;
  }
  root.expectation = { kind: 'underivable', reason: 'request_enumerates_several_clauses' };
  root.children = clauses.map(([clause, span]) => {
    const child = leafNode(root.node_id, clause, span, 1, deriveExpectation(clause));
    expand(child, maxSplitDepth);
    return child;
  });
  return root;
}

function expand(node, maxSplitDepth) {
  if (isObservable(node.expectation) || node.depth >= maxSplitDepth) return;
  const pieces = splitOnceCheckable(node.clause);
  if (pieces.length < 2) return;
  let cursor = 0;
  const children = [];
  for (const piece of pieces) {
    const trimmed = trim(piece);
    if (trimmed === '') continue;
    const offset = node.clause.slice(cursor).indexOf(trimmed);
    let span = node.span;
    if (offset >= 0) {
      const start = node.span[0] + utf8Len(node.clause.slice(0, cursor + offset));
      cursor += offset + trimmed.length;
      span = [start, start + utf8Len(trimmed)];
    }
    const child = leafNode(node.node_id, trimmed, span, Math.min(255, node.depth + 1), deriveExpectation(trimmed));
    expand(child, maxSplitDepth);
    children.push(child);
  }
  if (children.length >= 2) node.children = children;
}

/** Mirrors `ObligationNode::discharged`. */
export function discharged(node) {
  if (!node.children.length) return node.outcome.kind === 'satisfied' || node.outcome.kind === 'unsatisfiable';
  return node.children.every(discharged);
}

/** Mirrors `ObligationNode::collect_leaves`. */
export function collectLeaves(node, out = []) {
  if (!node.children.length) out.push(node);
  else for (const child of node.children) collectLeaves(child, out);
  return out;
}

/** Mirrors `fn mismatch_template`. */
export function mismatchTemplate(id, language) {
  const record = parseLinoRoot(readText('data/seed/obligation-mismatch.lino')).children
    .find((node) => findChildValue(node, 'record_type') === 'obligation_mismatch' && findChildValue(node, 'id') === id);
  if (!record) return '';
  const localized = findChildValue(record, language);
  return trim(localized) === '' ? findChildValue(record, 'en') : localized;
}

function mismatchSentence(node, id, bindings) {
  return bindings.reduce((sentence, [placeholder, value]) => sentence.split(placeholder).join(value),
    mismatchTemplate(id, detect(node.clause)));
}

/** Mirrors `ObligationNode::judge`: the outcome `record` reaches, or null. */
function judge(node, record) {
  const expectation = node.expectation;
  const satisfied = { kind: 'satisfied', record };
  const refuted = (id, bindings) => ({ kind: 'refuted', record, mismatch: mismatchSentence(node, id, bindings) });
  switch (expectation.kind) {
    case 'file_bytes': {
      if (!evidenceNames(record, expectation.path)) return null;
      if (expectation.sha256 !== null) {
        return record.observed_output_sha256 === expectation.sha256 ? satisfied : refuted('file_bytes_digest', [
          ['{path}', expectation.path], ['{observed}', record.observed_output_sha256], ['{expected}', expectation.sha256],
        ]);
      }
      return reportsSuccess(record) ? satisfied : refuted('file_bytes_no_success', [['{path}', expectation.path]]);
    }
    case 'command_exit':
      if (!evidenceNames(record, expectation.command)) return null;
      return record.exit_code === expectation.expected_exit ? satisfied : refuted('command_exit', [
        ['{command}', expectation.command],
        ['{observed}', record.exit_code === null ? 'none' : String(record.exit_code)],
        ['{expected}', String(expectation.expected_exit)],
      ]);
    case 'output_hash':
      if (!evidenceNames(record, expectation.command)) return null;
      return record.observed_output_sha256 === expectation.sha256 ? satisfied : refuted('output_hash', [
        ['{command}', expectation.command], ['{observed}', record.observed_output_sha256], ['{expected}', expectation.sha256],
      ]);
    case 'symbolic_check':
      if (!evidenceNames(record, expectation.check_id)) return null;
      return reportsSuccess(record) ? satisfied : refuted('symbolic_check', [['{check}', expectation.check_id]]);
    default:
      return null;
  }
}

/**
 * Mirrors `ObligationLedger::observe`: the node id the record moved, or null.
 * @param {{frame_id: string, root: object}} ledger
 */
export function observe(ledger, record) {
  for (const leaf of collectLeaves(ledger.root)) {
    if (leaf.outcome.kind === 'satisfied') continue;
    const outcome = judge(leaf, record);
    if (outcome !== null) {
      leaf.outcome = outcome;
      return leaf.node_id;
    }
  }
  return null;
}

function countOf(ledger, kind) {
  return collectLeaves(ledger.root).filter((leaf) => leaf.outcome.kind === kind).length;
}

/** Mirrors `ObligationLedger::every_obligation_discharged`. */
export const everyObligationDischarged = (ledger) => discharged(ledger.root);
/** Mirrors `ObligationLedger::satisfied_count`. */
export const satisfiedCount = (ledger) => countOf(ledger, 'satisfied');
/** Mirrors `ObligationLedger::unsatisfiable_count`. */
export const unsatisfiableCount = (ledger) => countOf(ledger, 'unsatisfiable');

//! Reading a request's clauses, and each clause's expectation, out of data.
//!
//! Plan 05 leaves 5, 6 and 7 own this file. The clause splitter is the one
//! `task_obligations` already splits on — the seeded enumeration cues — and the
//! expectation derivation is the rule set of
//! `data/meta/obligation-evidence-contract.lino`, so a new expectation shape is a
//! data edit rather than a `match` arm here.

use crate::agentic_coding::general_planner::GeneralChangePlan;
use crate::engine::stable_id;

use super::ObligationExpectation;

/// The clauses a request enumerates, each with its UTF-8 byte span in the
/// request exactly as the user wrote it.
///
/// The cut points are the seeded enumeration cues — the same role
/// `task_obligations` already splits on — but a cue only cuts where it *opens* a
/// clause: at the start of the request, or just after a sentence ends. A "first"
/// inside "whose first line is exactly `---`" describes a file's contents and
/// opens nothing (issue #1099).
///
/// The sentence terminators include `。`, `！`, `？` and `।` beside the Latin
/// ones, because a Chinese or Hindi request ends its sentences with those and a
/// splitter that does not know them reads five languages as one clause.
#[must_use]
pub fn clauses_with_spans(request: &str) -> Vec<(String, (usize, usize))> {
    let cues = crate::seed::lexicon().words_for_role(crate::seed::ROLE_ENUMERATION_CUE);
    if cues.is_empty() {
        return vec![(request.trim().to_owned(), (0, request.len()))];
    }
    let mut boundaries = vec![0_usize];
    for (index, _) in request.char_indices() {
        if index == 0 || !opens_a_clause(request, index) {
            continue;
        }
        let rest = request[index..].to_lowercase();
        if cues.iter().any(|cue| starts_with_cue(&rest, cue)) {
            boundaries.push(index);
        }
    }
    boundaries.push(request.len());
    boundaries.dedup();
    boundaries
        .windows(2)
        .filter_map(|window| {
            let raw = &request[window[0]..window[1]];
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                return None;
            }
            let start = window[0] + raw.find(trimmed)?;
            Some((trimmed.to_owned(), (start, start + trimmed.len())))
        })
        .collect()
}

/// Whether the byte at `index` begins a clause: everything before it either ends
/// a sentence, ends a line, or is nothing but whitespace.
///
/// The line break is read before trimming: `trim_end` would strip it, and a cue
/// opening a new line ("…\"Alpha\"\nThen, print …") would never cut (issue
/// #1166).
fn opens_a_clause(request: &str, index: usize) -> bool {
    let line_end = request[..index].trim_end_matches([' ', '\t', '\r']);
    let before = line_end.trim_end();
    before.is_empty()
        || line_end.ends_with('\n')
        || before.ends_with(['.', '!', '?', ';', ':', '。', '！', '？', '।', '॥'])
}

/// Whether `rest` opens with `cue` as a whole word — or, for a script that does
/// not space its words, as its own leading run of characters.
///
/// The word-boundary test is only meaningful where words are spaced. `然后确认`
/// is a cue followed immediately by the verb it introduces, and `确` is
/// alphanumeric, so demanding a non-alphanumeric follower reads Chinese and
/// Japanese as one clause and every enumerated obligation in those languages is
/// silently merged into the first.
fn starts_with_cue(rest: &str, cue: &str) -> bool {
    let Some(after) = rest.strip_prefix(cue) else {
        return false;
    };
    if cue.chars().any(is_unspaced_script) {
        return true;
    }
    after
        .chars()
        .next()
        .is_none_or(|character| !character.is_alphanumeric())
}

/// Whether a character belongs to a script that does not separate its words with
/// spaces: the CJK ideographs, the kana, and the Hangul syllables.
const fn is_unspaced_script(character: char) -> bool {
    matches!(character,
        '\u{3040}'..='\u{30ff}'
            | '\u{3400}'..='\u{4dbf}'
            | '\u{4e00}'..='\u{9fff}'
            | '\u{ac00}'..='\u{d7af}'
            | '\u{f900}'..='\u{faff}')
}

/// Read one clause's expectation out of the clause itself.
///
/// The composer that already plans a standalone request is the authority on what
/// artifact a clause names; when it reads one, the plan's own mode says which
/// shape of observation would settle the clause. When it reads none, a clause
/// that still names an observable action is a symbolic check, and a clause that
/// names neither is `Underivable` — kept, split, and finally reported, never
/// discarded.
#[must_use]
pub fn derive_expectation(clause: &str) -> ObligationExpectation {
    let rules = ExpectationRules::shipped();
    if let Some(plan) = crate::agentic_coding::general_planner::compose_general_change_plan(clause)
    {
        let rule = rules.for_plan_mode(plan.mode.slug());
        return shape_for(&plan, rule);
    }
    if crate::task_decomposition::is_checkable(clause) {
        let rule = rules.for_generated_check();
        if rule.is_none_or(|rule| rule.expectation == "symbolic_check") {
            return ObligationExpectation::SymbolicCheck {
                check_id: format!(
                    "obligation:{}",
                    stable_id("obligation_check", clause.trim())
                ),
            };
        }
    }
    ObligationExpectation::Underivable {
        reason: rules
            .for_absent_artifact()
            .map_or_else(|| String::from("no_artifact_in_clause"), |rule| rule.reason),
    }
}

/// Build the expectation a matched rule names out of the plan it matched.
///
/// Hashing the observed bytes is only honest when the request states what they
/// must be; when it does not, the rule's `otherwise` shape applies and the
/// observable claim is the command's exit status, never a digest nothing
/// declared (plan 05 risk 4).
fn shape_for(plan: &GeneralChangePlan, rule: Option<ExpectationRule>) -> ObligationExpectation {
    let Some(rule) = rule else {
        return ObligationExpectation::Underivable {
            reason: format!("no_rule_for_plan_mode_{}", plan.mode.slug()),
        };
    };
    let declared = expected_digest(&plan.content);
    let shape = match (&declared, rule.otherwise.as_deref()) {
        (None, Some(otherwise)) => otherwise,
        _ => rule.expectation.as_str(),
    };
    match shape {
        "file_bytes" => ObligationExpectation::FileBytes {
            path: plan.target.clone(),
            sha256: declared,
        },
        "output_hash" => declared.map_or_else(
            || ObligationExpectation::CommandExit {
                command: plan.verification_command.clone(),
                expected_exit: 0,
            },
            |sha256| ObligationExpectation::OutputHash {
                command: plan.verification_command.clone(),
                sha256,
            },
        ),
        "command_exit" => ObligationExpectation::CommandExit {
            command: plan.verification_command.clone(),
            expected_exit: 0,
        },
        "symbolic_check" => ObligationExpectation::SymbolicCheck {
            check_id: format!("obligation:{}", stable_id("obligation_check", &plan.goal)),
        },
        _ => ObligationExpectation::Underivable {
            reason: rule.reason,
        },
    }
}

/// One `rule` row of `data/meta/obligation-evidence-contract.lino`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExpectationRule {
    /// The rule's name, as the document writes it.
    pub name: String,
    /// The condition the rule fires on.
    pub when: String,
    /// The general-plan mode the condition narrows to, when it names one.
    pub mode: String,
    /// The expectation shape the rule names.
    pub expectation: String,
    /// The shape to use when the request declared no bytes to hash.
    pub otherwise: Option<String>,
    /// The reason an underivable rule records.
    pub reason: String,
}

/// The derivation rules, read from the contract document rather than written as
/// a `match` here, so a new expectation shape is a data edit (plan 05 leaf 6).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExpectationRules {
    /// The rule rows, in document order.
    pub rules: Vec<ExpectationRule>,
}

/// The contract document, embedded so the derivation needs no filesystem.
const CONTRACT_LINO: &str =
    include_str!("../../embedded/data/meta/obligation-evidence-contract.lino");

/// The `when` keys the contract's rule rows are addressed by. Each is one token,
/// because a rule condition is a key the document and this reader agree on, not
/// a sentence anybody reads.
const WHEN_PLAN_MODE: &str = "general_plan_mode";
/// The condition naming a clause a reader can already tell is done.
const WHEN_GENERATED_CHECK: &str = "generated_check";
/// The condition naming a clause with neither a plan nor an observable action.
const WHEN_NO_ARTIFACT: &str = "no_artifact";

impl ExpectationRules {
    /// Parse the checked-in contract.
    #[must_use]
    pub fn shipped() -> Self {
        Self::from_lino(CONTRACT_LINO)
    }

    /// Parse a contract document's `rule` rows.
    #[must_use]
    pub fn from_lino(text: &str) -> Self {
        let mut rules: Vec<ExpectationRule> = Vec::new();
        for line in text.lines() {
            let trimmed = line.trim();
            if let Some(name) = trimmed.strip_prefix("rule ") {
                rules.push(ExpectationRule {
                    name: unquoted(name.trim()),
                    when: String::new(),
                    mode: String::new(),
                    expectation: String::new(),
                    otherwise: None,
                    reason: String::new(),
                });
                continue;
            }
            let Some(rule) = rules.last_mut() else {
                continue;
            };
            if let Some(value) = field(trimmed, "when") {
                rule.when = value;
            } else if let Some(value) = field(trimmed, "mode") {
                rule.mode = value;
            } else if let Some(value) = field(trimmed, "expectation") {
                rule.expectation = value;
            } else if let Some(value) = field(trimmed, "otherwise") {
                rule.otherwise = Some(value);
            } else if let Some(value) = field(trimmed, "reason") {
                rule.reason = value;
            }
        }
        Self { rules }
    }

    /// The rule whose `when` names this general-plan mode.
    #[must_use]
    pub fn for_plan_mode(&self, mode: &str) -> Option<ExpectationRule> {
        self.rules
            .iter()
            .find(|rule| rule.when == WHEN_PLAN_MODE && rule.mode == mode)
            .cloned()
    }

    /// The rule that governs a clause carrying a generated check.
    #[must_use]
    pub fn for_generated_check(&self) -> Option<ExpectationRule> {
        self.matching(WHEN_GENERATED_CHECK)
    }

    /// The rule that governs a clause naming no artifact at all.
    #[must_use]
    pub fn for_absent_artifact(&self) -> Option<ExpectationRule> {
        self.matching(WHEN_NO_ARTIFACT)
    }

    fn matching(&self, when: &str) -> Option<ExpectationRule> {
        self.rules.iter().find(|rule| rule.when == when).cloned()
    }
}

/// Read `key "value"` from a contract line when the key matches exactly.
fn field(line: &str, key: &str) -> Option<String> {
    let rest = line.strip_prefix(key)?;
    if !rest.starts_with(char::is_whitespace) {
        return None;
    }
    Some(unquoted(rest.trim()))
}

/// Strip one pair of surrounding quotes, if the value carries them.
fn unquoted(raw: &str) -> String {
    raw.strip_prefix('"')
        .and_then(|value| value.strip_suffix('"'))
        .unwrap_or(raw)
        .to_owned()
}

/// The digest a read-back of the requested bytes must produce.
///
/// Two normalizations, and both are about the difference between the prose and
/// the file. The sentence that states the bytes ends with its own full stop —
/// "containing Gemfile.lock." names twelve bytes, not thirteen — and the file a
/// write produces ends with exactly one newline, which is what the verification
/// command `cat <path>` observes. Content the request never stated yields no
/// digest at all rather than a guessed one.
#[must_use]
pub fn expected_digest(content: &str) -> Option<String> {
    let stated = content.trim_end();
    let stated = stated
        .strip_suffix(['.', '。', '।', '!', '？', '?'])
        .unwrap_or(stated)
        .trim_end();
    if stated.is_empty() {
        return None;
    }
    let normalized = if stated.ends_with('\n') {
        stated.to_owned()
    } else {
        format!("{stated}\n")
    };
    Some(crate::source_fetch::sha256_hex(normalized.as_bytes()))
}
